interface FormattedCellProps<T extends React.ReactNode> {
    value: T;
    format?: (value: T) => React.ReactNode;
    align?: 'left' | 'right' | 'center';
}

export function FormattedCell<T extends React.ReactNode>({
    value,
    format,
    align = 'left'
}: FormattedCellProps<T>) {
    const alignmentClass = align === 'right' ? 'text-right' : align === 'center' ? 'text-center' : 'text-left';

    return (
        <div className={alignmentClass}>
            <p className="text-muted-foreground text-sm font-light">
                {format ? format(value) : value}
            </p>
        </div>
    );
}

import { FormattedCell } from "./formatted.cell";

export function TextCell({ value }: { value: string }) {
    return <FormattedCell value={value} align="left" />
}

import { FormattedCell } from "./formatted.cell";

export function EmailCell({ value }: { value: string }) {
    return <FormattedCell value={value} align="left" />
}

import { FormattedCell } from "./formatted.cell";
import { dateFormatter } from "./formatters.utils";

export function DateCell({ value }: { value: string }) {
    return <FormattedCell value={value} align="left" format={(value) => dateFormatter(value)} />
}

import { FormattedCell } from "./formatted.cell";
import { currencyFormatter } from "./formatters.utils";

export function CurrencyCell({ value }: { value: number }) {
    return <FormattedCell value={value} align="right" format={(value) => currencyFormatter(value)} />
}

import { FormattedCell } from "./formatted.cell";
import { checkBoxFormatter } from "./formatters.utils";

export function CheckboxCell({ value }: { value?: boolean }) {
    return <FormattedCell value={value} align="center" format={(value) => checkBoxFormatter(value)} />
}

import type { VariantProps } from 'class-variance-authority';
import { Badge, badgeVariants } from '@/components/ui/badge';

type BadgeVariant = VariantProps<typeof badgeVariants>['variant'];

type BadgeCellProps = {
    value: string;
    variant?: BadgeVariant;
    variantByValue?: Record<string, BadgeVariant>;
};

export function BadgeCell({ value, variant = 'secondary', variantByValue }: BadgeCellProps) {
    return <Badge variant={variantByValue?.[value] ?? variant}>{value}</Badge>;
}

import { Square, SquareCheck } from "lucide-react";

export function checkBoxFormatter(value: boolean | undefined) {
    return value ? <SquareCheck /> : <Square />;
}

export function currencyFormatter(value: number) {
    const symbol = import.meta.env.VITE_CURRENCY_SYMBOL ?? "€";
    return `${symbol} ${(value / 100).toFixed(2)}`;
}

export function minutesFormatter(value: number) {
    const hours = Math.floor(value / 60);
    const minutes = value % 60;

    if (hours === 0) {
        return `${minutes}m`;
    }
    return `${hours}h ${minutes}m`;
}

export function nationalNumberFormatter(value: string) {
    if (!value || value.trim().length == 0) return '';

    const formattedString = value.slice(0, 2) + '.' + value.slice(2, 4) + '.' + value.slice(4, 6) + '-' + value.slice(6, 9) + '.' + value.slice(9);
    return formattedString;
}

export function dateFormatter(value: string) {
    const format = import.meta.env.VITE_DATE_FORMAT ?? "YYYY/MM/DD";
    return formatDate(new Date(value), format);
}

function formatDate(date: Date, format: string) {
    const year = String(date.getFullYear());
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");

    return format
        .replace("YYYY", year)
        .replace("MM", month)
        .replace("DD", day);
}
